-- ==================== FUNGSI LOGGING ====================
local function log(msg, isError)
    if Config.ShowLogs then
        if isError then
            warn("[SAMBUNG KATA] " .. msg)
        else
            print("[SAMBUNG KATA] " .. msg)
        end
    end
end

-- ==================== FUNGSI INDEX DATABASE ====================
local function rebuildIndex()
    State.IndexedDB = {}
    for _, word in ipairs(kataKBBI) do
        local upper = word:upper()
        local first = upper:sub(1,1)
        if not State.IndexedDB[first] then State.IndexedDB[first] = {} end
        table.insert(State.IndexedDB[first], upper)
    end
    log("Database di-rebuild, total kata: " .. #kataKBBI)
end
rebuildIndex()

-- ==================== FUNGSI UTILITAS ====================
local function forceClear()
    for i = 1, 20 do
        VIM:SendKeyEvent(true, Enum.KeyCode.Backspace, false, game)
        task.wait(0.005)
        VIM:SendKeyEvent(false, Enum.KeyCode.Backspace, false, game)
    end
end

local function cleanText(str)
    if not str then return "" end
    local cleaned = str:gsub("<[^>]+>", "")
    cleaned = cleaned:gsub("%s+", " ")
    return cleaned
end

-- Ekstrak prefix dari teks (hanya 1-3 huruf)
local function extractPrefix(teks)
    teks = cleanText(teks):upper()
    -- Cari setelah titik dua
    local prefix = teks:match(":[%s]*([%a]+)")
    if prefix then
        if #prefix <= 3 then
            log("Prefix ditemukan via titik dua: " .. prefix)
            return prefix
        else
            log("Setelah titik dua terlalu panjang (" .. #prefix .. "), diabaikan: " .. prefix)
        end
    end
    -- Coba ambil kata terakhir jika panjang <= 3
    local words = {}
    for w in teks:gmatch("%a+") do
        table.insert(words, w)
    end
    if #words > 0 then
        local last = words[#words]
        if #last <= 3 then
            log("Prefix ditemukan via kata pendek: " .. last)
            return last
        end
    end
    log("Tidak ada prefix dalam teks: " .. teks, true)
    return nil
end

local function get5Options(awalan)
    awalan = awalan:upper()
    local firstLetter = awalan:sub(1,1)
    local candidates = State.IndexedDB[firstLetter] or {}
    local validWords = {}
    
    for _, kata in ipairs(candidates) do
        if kata:sub(1, #awalan) == awalan and not State.UsedWords[kata] and #kata > #awalan then
            table.insert(validWords, kata)
        end
    end

    if Config.LengthMode == "Sombong (Panjang)" then
        table.sort(validWords, function(a, b) return #a > #b end)
    elseif Config.LengthMode == "Cepat (Pendek)" then
        table.sort(validWords, function(a, b) return #a < #b end)
    else
        for i = #validWords, 2, -1 do
            local j = math.random(i)
            validWords[i], validWords[j] = validWords[j], validWords[i]
        end
    end

    local finalResults = {}
    local activeTraps = TrapDict[Config.TrapDifficulty] or {}
    if Config.TrapMode then
        for i = #validWords, 1, -1 do
            if activeTraps[validWords[i]:sub(-1)] then 
                table.insert(finalResults, {word = validWords[i], pref = awalan})
                table.remove(validWords, i)
            end
        end
    end
    for i=1, math.min(5 - #finalResults, #validWords) do
        table.insert(finalResults, {word = validWords[i], pref = awalan})
    end
    return finalResults
end

local function ketikOpsi(data)
    if State.IsBusy then return end
    State.IsBusy = true
    
    local word = data.word
    local pref = data.pref
    local toType = word
    
    if Config.ContinuationOnly and word:sub(1, #pref) == pref then
        toType = word:sub(#pref + 1)
        log("Mengetik sisa: " .. toType .. " (dari " .. word .. ")")
    else
        log("Mengetik full: " .. word)
    end

    forceClear()
    task.wait(Config.DelayBeforeType)

    for i = 1, #toType do
        local char = toType:sub(i, i)
        if math.random(1, 100) <= Config.TypoChance and NearKeys[char] then
            local wrong = NearKeys[char][math.random(#NearKeys[char])]
            VIM:SendKeyEvent(true, wrong, false, game)
            task.wait(0.05)
            VIM:SendKeyEvent(false, wrong, false, game)
            task.wait(0.1)
            VIM:SendKeyEvent(true, "Backspace", false, game)
            task.wait(0.05)
            VIM:SendKeyEvent(false, "Backspace", false, game)
        end
        VIM:SendKeyEvent(true, char, false, game)
        task.wait(Config.TypingSpeed)
        VIM:SendKeyEvent(false, char, false, game)
    end
    
    task.wait(0.1)
    VIM:SendKeyEvent(true, Enum.KeyCode.Return, false, game)
    VIM:SendKeyEvent(false, Enum.KeyCode.Return, false, game)
    
    State.UsedWords[word] = true
    State.CountUsed = State.CountUsed + 1
    State.LastTryTime = tick()
    log("Kata terkirim: " .. word .. " (total: " .. State.CountUsed .. ")")
    task.wait(1)
    State.IsBusy = false
end

