-- ==================== ENGINE UTAMA ====================
task.spawn(function()
    while true do
        task.wait(0.3)
        if not (Config.AutoActive or Config.ESPEnabled) then
            LblStatus:Set("Status: Idle")
            continue
        end

        -- Cari target UI
        local targetUI = nil
        if Config.TargetUIName ~= "" then
            for _, gui in ipairs(LP.PlayerGui:GetChildren()) do
                if gui:IsA("ScreenGui") then
                    local found = gui:FindFirstChild(Config.TargetUIName, true)
                    if found and (found:IsA("TextLabel") or found:IsA("TextButton")) and found.Visible then
                        targetUI = found
                        break
                    end
                end
            end
        else
            -- Scan otomatis jika tidak ada nama
            for _, gui in ipairs(LP.PlayerGui:GetChildren()) do
                if gui:IsA("ScreenGui") and gui.Enabled then
                    for _, obj in ipairs(gui:GetDescendants()) do
                        if (obj:IsA("TextLabel") or obj:IsA("TextButton")) and obj.Visible and obj.Text ~= "" then
                            local t = cleanText(obj.Text):upper()
                            local isBlacklisted = false
                            for _, bl in ipairs(Config.Blacklist) do
                                if t:find(bl) then isBlacklisted = true break end
                            end
                            if isBlacklisted then continue end
                            if extractPrefix(t) then
                                targetUI = obj
                                break
                            end
                        end
                    end
                end
                if targetUI then break end
            end
        end

        if not targetUI then
            LblStatus:Set("Status: Mencari UI...")
            continue
        end

        -- Ambil prefix
        local prefix = extractPrefix(targetUI.Text)
        if not prefix then
            LblStatus:Set("Status: Tidak ada prefix")
            continue
        end

        LblDet:Set("Terdeteksi: " .. prefix)
        LblPrefix:Set("Prefix terakhir: " .. prefix)
        LblStatus:Set("Status: Memproses...")
        log("Prefix terdeteksi: " .. prefix)

        -- Update jika prefix baru
        if prefix ~= State.LastPromptRaw then
            State.LastPromptRaw = prefix
            State.MatchIndex = 1
            State.CurrentMatches = get5Options(prefix)
            log("Mendapatkan " .. #State.CurrentMatches .. " opsi untuk prefix " .. prefix)
            
            -- Update ESP
            if Config.ESPEnabled then
                for i=1, 5 do
                    if State.CurrentMatches[i] then
                        ESPBtns[i].Text = State.CurrentMatches[i].word
                        ESPBtns[i].Visible = true
                    else
                        ESPBtns[i].Visible = false
                    end
                end
            end
        end

        -- Auto answer jika aktif
        if Config.AutoActive and not State.IsBusy then
            if #State.CurrentMatches >= State.MatchIndex then
                ketikOpsi(State.CurrentMatches[State.MatchIndex])
                LblUsed:Set("🔥 Kata digunakan: " .. State.CountUsed)
            else
                State.MatchIndex = 1
                log("Tidak ada opsi lagi untuk prefix " .. prefix)
            end
        elseif Config.AutoActive and tick() - State.LastTryTime > Config.RetryDelay and #State.CurrentMatches > State.MatchIndex then
            State.MatchIndex = State.MatchIndex + 1
            if #State.CurrentMatches >= State.MatchIndex then
                ketikOpsi(State.CurrentMatches[State.MatchIndex])
            end
        end
    end
end)

